**Minor suggestion:** The two branches share identical tail logic (`WithRequestTrace` + `return log.WithLogger`). Deduplicating would make it clearer that the only difference is how `rt` is obtained.

```go
func detachTemplateImageJobContext(ctx context.Context, fields map[string]any) context.Context {
	detached := context.Background()
	rt := CubeLog.GetTraceInfo(ctx)
	if rt == nil {
		name := "template_job"
		if component, ok := fields["component"].(string); ok && component != "" {
			name = component
		}
		rt = &CubeLog.RequestTrace{
			Action:         name,
			Caller:         name,
			Callee:         constants.CubeMasterServiceID,
			CalleeEndpoint: "localhost",
			Timestamp:      time.Now(),
		}
	} else {
		rt = rt.DeepCopy()
	}
	detached = CubeLog.WithRequestTrace(detached, rt)
	return log.WithLogger(detached, log.G(ctx).WithFields(fields))
}
