+	}
+	if out.MemRatio <= 0 {
+		out.MemRatio = defaultMemOvercommitRatio
+	}
+	return out
+}

body:
**Security: NaN/Inf float64 values bypass the `<= 0` guard**

Go's `math.NaN() <= 0` evaluates to `false`, and `math.Inf(1) <= 0` is also `false`. Since YAML 1.2 supports `.nan`, `.inf`, and `-.inf`, an operator could set `cpu_ratio: .nan` and it would pass through undetected. When `EffectiveQuotaCpu` computes `int64(float64(quota) * NaN)`, the NaN propagates and `int64(NaN)` on amd64 returns `math.MinInt64` (~-9.2e18), making every node appear to have negative free capacity.

```suggestion
func (c OvercommitRatioConf) sanitized() OvercommitRatioConf {
	out := c
	if out.CPURatio <= 0 || math.IsNaN(out.CPURatio) || math.IsInf(out.CPURatio, 0) {
		out.CPURatio = defaultCPUOvercommitRatio
	}
	if out.MemRatio <= 0 || math.IsNaN(out.MemRatio) || math.IsInf(out.MemRatio, 0) {
		out.MemRatio = defaultMemOvercommitRatio
	}
	return out
}
```

(`math` is already imported at the top of this file.)

